using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Threading;using ViewportCap.App.Services;using ViewportCap.Core;using Point=System.Windows.Point;using MouseEventArgs=System.Windows.Input.MouseEventArgs;using KeyEventArgs=System.Windows.Input.KeyEventArgs;using Cursors=System.Windows.Input.Cursors;
namespace ViewportCap.App.Windows;
public partial class RegionOverlayWindow:Window
{
 private readonly MonitorDescriptor _monitor;private bool _dragging;private Point _start;private DispatcherTimer? _hintTimer;public event Action<CaptureRegion>? SelectionCompleted;public event Action? Cancelled;public MonitorDescriptor Monitor=>_monitor;
 public RegionOverlayWindow(MonitorDescriptor monitor){InitializeComponent();_monitor=monitor;var b=DisplayService.GetWindowBounds(monitor);Left=b.Left;Top=b.Top;Width=b.Width;Height=b.Height;SourceInitialized+=(_,_)=>WindowAffinity.ExcludeFromCapture(this);Loaded+=(_,_)=>UpdateShades(default,false);SizeChanged+=(_,_)=>UpdateShades(default,false);}
 public void EnableInput(bool enabled){IsHitTestVisible=enabled;Cursor=enabled?Cursors.Cross:Cursors.Arrow;if(enabled){Activate();Focus();}}
 private void Window_MouseLeftButtonDown(object s,MouseButtonEventArgs e){if(!IsHitTestVisible)return;_dragging=true;_start=e.GetPosition(RootCanvas);CaptureMouse();UpdateSelection(_start,_start);e.Handled=true;}
 private void Window_MouseMove(object s,MouseEventArgs e){if(_dragging)UpdateSelection(_start,e.GetPosition(RootCanvas));}
 private void Window_MouseLeftButtonUp(object s,MouseButtonEventArgs e){if(!_dragging)return;_dragging=false;ReleaseMouseCapture();var p=e.GetPosition(RootCanvas);var r=RegionMath.ToPhysical(RegionMath.Normalize(_start.X,_start.Y,p.X,p.Y),_monitor);if(r.IsValid)SelectionCompleted?.Invoke(r);else{ShowHint();UpdateShades(default,false);}e.Handled=true;}
 private void Window_MouseRightButtonDown(object s,MouseButtonEventArgs e)=>Cancelled?.Invoke();private void Window_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Escape)Cancelled?.Invoke();}
 private void UpdateSelection(Point a,Point b){var r=RegionMath.Normalize(a.X,a.Y,b.X,b.Y);UpdateShades(r,true);var ph=RegionMath.ToPhysical(r,_monitor);SizeText.Text=$"{ph.Width} x {ph.Height}";Canvas.SetLeft(SizeBadge,Math.Min(r.Left,Math.Max(0,RootCanvas.ActualWidth-90)));Canvas.SetTop(SizeBadge,r.Top>30?r.Top-28:r.Top+4);}
 private void UpdateShades(DragRect r,bool selected){var w=RootCanvas.ActualWidth;var h=RootCanvas.ActualHeight;if(!selected){FullShade.Visibility=Visibility.Visible;FullShade.Width=w;FullShade.Height=h;foreach(FrameworkElement x in new FrameworkElement[]{TopShade,BottomShade,LeftShade,RightShade,SelectionBorder,SizeBadge})x.Visibility=Visibility.Collapsed;return;}FullShade.Visibility=Visibility.Collapsed;foreach(var x in new[]{TopShade,BottomShade,LeftShade,RightShade})x.Visibility=Visibility.Visible;var l=Math.Clamp(r.Left,0,w);var t=Math.Clamp(r.Top,0,h);var right=Math.Clamp(r.Right,0,w);var bot=Math.Clamp(r.Bottom,0,h);SetRect(TopShade,0,0,w,t);SetRect(BottomShade,0,bot,w,h-bot);SetRect(LeftShade,0,t,l,bot-t);SetRect(RightShade,right,t,w-right,bot-t);SetRect(SelectionBorder,l,t,right-l,bot-t);SelectionBorder.Visibility=SizeBadge.Visibility=Visibility.Visible;}
 private void ShowHint(){HintText.Visibility=Visibility.Visible;Canvas.SetLeft(HintText,16);Canvas.SetTop(HintText,16);_hintTimer?.Stop();_hintTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1.5)};_hintTimer.Tick+=(_,_)=>{_hintTimer.Stop();HintText.Visibility=Visibility.Collapsed;};_hintTimer.Start();}
 private static void SetRect(FrameworkElement e,double l,double t,double w,double h){e.Width=Math.Max(0,w);e.Height=Math.Max(0,h);Canvas.SetLeft(e,l);Canvas.SetTop(e,t);}
}
